async function seed() {
  console.log('Connecting to MongoDB...');
  await mongoose.connect(DB_URL);
  console.log('Connected to MongoDB');

  // Clean up existing AI path
  const existingPath = await PracticePath.findOne({ slug: 'artificial-intelligence' });
  if (existingPath) {
    const topicIds = await PracticeTopic.find({ practicePath: existingPath._id }).distinct('_id');
    await PracticeQuestion.deleteMany({ topic: { $in: topicIds } });
    await PracticeSubtopic.deleteMany({ topic: { $in: topicIds } });
    await PracticeTopic.deleteMany({ practicePath: existingPath._id });
    await PracticePath.deleteOne({ _id: existingPath._id });
    console.log('Cleaned existing AI practice data');
  }

  const path = await PracticePath.create({
    title: 'Artificial Intelligence',
    slug: 'artificial-intelligence',
    description: 'Master AI from fundamentals to advanced topics including ML, Deep Learning, NLP, Computer Vision, and more.',
    level: 'Intermediate',
    themeColor: '#8b5cf6',
    gradientFrom: '#8b5cf6',
    gradientTo: '#4c1d95',
    estimatedDuration: '40+ hours',
    order: 2,
    isPublished: true,
  });
  console.log('Created path: ' + path.title);

  let totalTopics = 0;
  let totalSubtopics = 0;
  let totalQuestions = 0;

  for (let ti = 0; ti < TOPICS.length; ti++) {
    const t = TOPICS[ti];
    const topic = await PracticeTopic.create({
      practicePath: path._id,
      title: t.title,
      slug: t.slug,
      description: t.description,
      order: ti + 1,
      isPublished: true,
    });
    totalTopics++;
    console.log(`Topic ${ti + 1}: ${topic.title}`);

    for (let si = 0; si < t.subtopics.length; si++) {
      const s = t.subtopics[si];
      const subtopic = await PracticeSubtopic.create({
        topic: topic._id,
        practicePath: path._id,
        title: s.title,
        slug: t.slug + '-' + s.slug,
        description: 'Practice questions for: ' + s.title,
        order: si + 1,
        isPublished: true,
      });
      totalSubtopics++;

      for (let qi = 0; qi < s.questions.length; qi++) {
        const q2 = s.questions[qi];
        await PracticeQuestion.create({
          practicePath: path._id,
          topic: topic._id,
          subtopic: subtopic._id,
          title: q2.title,
          slug: t.slug + '-' + q2.slug,
          difficulty: q2.difficulty,
          type: 'mcq',
          statement: q2.statement,
          options: q2.options,
          explanation: q2.explanation,
          order: qi + 1,
          isPublished: true,
          tags: ['ai', 'ai-full-seed'],
        });
        totalQuestions++;
      }
      console.log(`  Subtopic ${si + 1}: ${s.title} — ${s.questions.length} questions`);
    }
  }

  console.log('\n=== Seed Complete ===');
  console.log(`Topics: ${totalTopics}`);
  console.log(`Subtopics: ${totalSubtopics}`);
  console.log(`Questions: ${totalQuestions}`);
  await mongoose.disconnect();
  console.log('Disconnected from MongoDB');
}

seed().catch(err => {
  console.error('Seed failed:', err);
  process.exit(1);
});